(function(){
'use strict';
const M=JobModel, KEY='zhiyu-prototype-v1';
let s;try{s=JSON.parse(localStorage.getItem(KEY))}catch{}if(!s||s.version!==1)s=M.seed();
let mode='web',page='jobs',id='',query='',filters={},sort='recent',pageNo=1,pending='';
const $=x=>document.querySelector(x), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'⌕',jobs:'▤',favorites:'♡',mine:'◉',dashboard:'▦',review:'☑',sources:'◈',runs:'↻',ai:'✧',dictionary:'☷',feedback:'☏',users:'♙',plans:'◇',orders:'▣',refunds:'↩',ledger:'≡',login:'↪',history:'◷',member:'✦'};
const C={jobs:['C01','发现职位'],detail:['C03','岗位详情'],company:['C04','公司主页'],favorites:['C05','我的收藏'],mine:['C06','个人中心'],login:['C07','登录'],about:['C09','数据说明'],member:['C13','会员中心'],checkout:['C14','确认订单'],payment:['C15','支付结果'],orders:['C16','我的订单'],order:['C17','订单与售后'],history:['C18','已看与额度']};
const A={login:['A01','后台登录'],dashboard:['A02','工作台'],jobs:['A03','岗位管理'],edit:['A04','编辑岗位'],review:['A05','内容审核'],sources:['A06','数据源管理'],runs:['A07','采集任务'],ai:['A08','AI 配置'],dictionary:['A09','公司与字典'],feedback:['A10','用户反馈'],users:['A12','用户与会员'],plans:['A13','套餐配置'],orders:['A14','支付订单'],refunds:['A15','退款与售后'],ledger:['A16','额度流水']};
function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch{toast('浏览器未允许保存，刷新后演示状态可能丢失')}}
function bindingDialog(status='待关联'){modal('网站与小程序账号关联',`<div class="status-hero"><h2>${status}</h2><p>${status==='关联成功'?'演示账户已关联，三端共享同一份额度。':status==='账号冲突'?'该身份已关联其他账户，需人工核实，不自动合并两份额度。':status==='已过期'?'关联请求已过期，请重新发起。':status==='已取消'?'关联已取消，未更改账户。':'请在小程序确认本次关联。正式版需完成身份验证。'}</p></div><div class="note demo">仅演示交互状态，不读取微信身份，不执行真实账户合并。</div><div class="scenario-grid space">${['关联成功','已过期','已取消','账号冲突'].map(t=>btn('模拟'+t,'binding-state',t)).join('')}</div>`)}
function date(n){return new Date(n+8*3600000).toISOString().slice(0,16).replace('T',' ')}
function job(jid){return s.jobs.find(j=>j.id===jid)}
function btn(label,act,arg='',cls=''){return `<button class="btn ${cls}" data-act="${act}" data-id="${esc(arg)}">${label}</button>`}
function link(label,p,i='',cls=''){return btn(label,'go',p+(i?'/'+i:''),cls)}
function pill(t,c='green'){return `<span class="pill ${c}">${esc(t)}</span>`}
function empty(title,desc,action=''){return `<div class="empty"><div class="empty-icon">⌕</div><h3>${title}</h3><p>${desc}</p>${action}</div>`}
function head(title,desc='',action=''){return `<div class="row between space"><div><h1>${title}</h1><p class="sub">${desc}</p></div>${action}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('暂无记录','完成对应操作后，记录会显示在这里。')}</td></tr>`}</tbody></table></div>`}
function title(){return (mode==='admin'?A:C)[page]||(mode==='admin'?A.dashboard:C.jobs)}
function go(p,i='',m=mode){const target='#'+m+'/'+p+(i?'/'+encodeURIComponent(i):'');if(location.hash===target)render();else location.hash=target;close()}
function readRoute(){const a=location.hash.slice(1).split('/');mode=['web','mini','admin'].includes(a[0])?a[0]:'web';page=a[1]||(mode==='admin'?'dashboard':'jobs');id=decodeURIComponent(a.slice(2).join('/'));if(!(mode==='admin'?A:C)[page])page=mode==='admin'?'dashboard':'jobs';render();window.scrollTo(0,0)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(t,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${t}</h2>${btn('×','close','','text')}</div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!d.open)d.showModal()}
function close(){const d=$('#modal');if(d.open)d.close()}
function needLogin(target){if(s.logged)return true;pending=target||page+(id?'/'+id:'');go('login');return false}
function quota(){const b=M.balance(s);return `<div class="quota-card card"><div class="row between"><span>${s.logged?esc(s.user):'登录后领取每日额度'}</span>${pill(b.tier==='普通'?'免费用户':b.tier+' 会员')}</div><div class="quota-number">${b.base}<small> / ${b.limit} 次</small></div><p>今日可解锁新岗位</p><div class="progress"><span style="width:${b.base/b.limit*100}%"></span></div><p class="tiny">${b.credit?`另有 ${b.credit} 次补偿额度 · 优先使用`:'每日 00:00 更新 · 已看岗位免费回看'}</p>${link(s.logged?'查看会员权益':'登录领取额度',s.logged?'member':'login','','full')}</div>`}
function render(){const meta=title();$('#app').innerHTML=`<div class="prototype-bar"><div class="row"><strong>职遇 <span class="tiny">PROTOTYPE</span></strong><span class="pill">交互原型 v1.0</span></div><div class="switcher">${['web','mini','admin'].map((m,i)=>`<button data-act="mode" data-id="${m}" class="${mode===m?'active':''}">${['C 端网站','微信小程序','管理后台'][i]}</button>`).join('')}</div><div class="proto-actions"><button data-act="catalog">${meta[0]} 页面目录</button><button data-act="scenarios">演示工具</button><button data-act="reset">重置</button></div></div>${mode==='admin'?adminShell():mode==='mini'?miniShell():webShell()}`;save()}
function webShell(){return `<header class="site-header"><div class="brand" data-act="go" data-id="jobs"><span class="logo">职</span><strong>职遇</strong><span class="muted tiny">让机会更清晰</span></div><nav class="site-nav">${[['jobs','发现职位'],['favorites','我的收藏'],['history','已看岗位'],['member','会员权益']].map(([p,t])=>`<button class="${page===p?'active':''}" data-act="go" data-id="${p}">${t}</button>`).join('')}</nav><div class="header-right"><span class="tiny muted">今日剩余 <b>${M.balance(s).base}</b> 次</span>${s.logged?btn('林','go','mine','avatar'):link('登录 / 注册','login','','primary')}</div></header><main class="page-wrap">${consumer()}</main><footer class="footnote">职遇 · 招聘信息聚合交互原型　｜　全部岗位与公司均为虚构演示数据　${link('数据与服务说明','about','','text')}</footer>`}
function miniShell(){return `<main class="mobile-stage"><div class="phone"><div class="phone-status"><strong>9:41</strong><span>▮▮▮　▰</span></div><div class="phone-title"><button class="btn text" data-act="go" data-id="jobs">${page==='jobs'?'职遇':'‹'}</button><strong>${title()[1]}</strong><span class="capsule">••• │ ◉</span></div><div class="phone-content"><div class="page-wrap">${consumer()}</div></div><div class="phone-tabs">${[['jobs','职位'],['favorites','收藏'],['mine','我的']].map(([p,t])=>`<button data-act="go" data-id="${p}" class="${page===p?'active':''}"><span>${icons[p]}</span>${t}</button>`).join('')}</div></div><aside class="mobile-notes"><span class="page-id">WECHAT MINI PROGRAM / ${title()[0]}</span><h1>机会，随手可达。</h1><p>筛选合适的岗位，确认后解锁详情。三端共享这份演示数据。</p><div class="card"><h3>建议体验路径</h3>${['免费筛选职位','登录并解锁 1 个岗位','再次查看，验证不扣次','选择会员，模拟微信支付','切到后台处理反馈'].map((t,i)=>`<div class="flow-step"><span class="step-number">${i+1}</span>${t}</div>`).join('')}</div><div class="note demo">这是浏览器中的小程序原型，未接入微信登录或真实支付。价格待定，所有交易均为模拟。</div><p class="tiny">演示日期 ${M.day(s)} · 北京时间<br>顶部“演示工具”可切换额度耗尽、支付受限等场景。</p></aside></main>`}
function consumer(){switch(page){case'jobs':return jobsPage();case'detail':return detailPage();case'company':return companyPage();case'favorites':return favoritesPage();case'mine':return minePage();case'login':return loginPage();case'about':return aboutPage();case'member':return memberPage();case'checkout':return checkoutPage();case'payment':return paymentPage();case'orders':return ordersPage();case'order':return orderPage();case'history':return historyPage();default:return jobsPage()}}
function jobCard(j){const seen=!!s.unlocks[j.id];return `<article class="job-card"><div class="row between"><div><button class="job-title" data-act="go" data-id="detail/${j.id}">${esc(j.title)}</button><div class="meta">${esc(j.city)}<i>·</i>${esc(j.exp)}<i>·</i>${esc(j.education)}</div></div><strong class="salary">${esc(j.salary)}</strong></div><div class="tags">${j.tags.map(t=>`<span>${esc(t)}</span>`).join('')}${seen?pill('已解锁 · 免费回看'):j.status==='已结束'?pill('已结束','orange'):''}</div><div class="job-footer"><button class="row btn text" data-act="go" data-id="company/${esc(j.company)}"><span class="company-logo ${j.tone}">${esc(j.letter)}</span><span>${esc(j.company)}<small class="muted"> · ${esc(j.industry)}</small></span></button><div class="row"><span class="source-text">${esc(j.source)} · 今日核验</span><button class="btn text" aria-label="收藏${esc(j.title)}" data-act="favorite" data-id="${j.id}">${s.favorites.includes(j.id)?'♥':'♡'}</button></div></div></article>`}
function filterFields(){return [['city','城市',['成都','杭州','上海','深圳']],['industry','行业',s.dictionary.industry],['category','职能',s.dictionary.category],['exp','工作经验',['应届/实习','1–3年','3–5年','5年以上']],['type','招聘类型',['社招','校招','实习']],['education','学历',['本科','大专']]].map(([k,t,v])=>`<div class="filter-group"><label>${t}</label><select aria-label="${t}" data-filter="${k}"><option value="">不限${t}</option>${v.map(x=>`<option ${filters[k]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`).join('')}
function filtered(){let a=s.jobs.filter(j=>j.published&&j.status==='在招'&&(!query||`${j.title} ${j.company} ${j.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&Object.entries(filters).every(([k,v])=>!v||j[k]===v));if(sort==='salary')a.sort((a,b)=>(/K$/.test(b.salary)?parseInt(b.salary):0)-(/K$/.test(a.salary)?parseInt(a.salary):0));else a.sort((a,b)=>b.verified.localeCompare(a.verified));return a}
function jobsPage(){const a=filtered(),count=4,total=Math.max(1,Math.ceil(a.length/count));pageNo=Math.min(pageNo,total);return `<section class="hero"><div><div class="row tiny muted">精选信息 · 每日更新 · 来源可查</div><h1>下一站，遇见更好的机会。</h1><p>把分散的招聘信息，整理成你的下一步。</p><form data-form="search" class="searchbar"><span>⌕</span><input name="query" aria-label="搜索岗位或公司" placeholder="搜索岗位、公司或技能" value="${esc(query)}"><button class="btn primary">搜索职位</button></form><div class="row tiny">热门搜索：${['Java','产品','运营'].map(t=>btn(t,'hot',t,'text')).join('')}</div></div><svg class="hero-art" width="225" height="160" viewBox="0 0 225 160" aria-hidden="true"><circle cx="143" cy="78" r="72" fill="#d6e9db"/><rect x="52" y="32" width="120" height="107" rx="12" fill="white" transform="rotate(-8 52 32)"/><rect x="78" y="42" width="46" height="8" rx="4" fill="#8bbca6"/><rect x="78" y="65" width="70" height="5" rx="2" fill="#e2eae3"/><rect x="78" y="80" width="60" height="5" rx="2" fill="#e2eae3"/><circle cx="155" cy="113" r="28" fill="#16785f"/><path d="m142 113 9 9 17-20" fill="none" stroke="white" stroke-width="5" stroke-linecap="round"/></svg></section><div class="mobile-filterbar">${btn('☷ 筛选条件','filters','','small')}${Object.values(filters).filter(Boolean).map(x=>pill(x)).join('')}</div><div class="jobs-layout"><aside class="filters card"><div class="row between"><h3>筛选条件</h3>${btn('重置','clearfilters','','text tiny')}</div>${filterFields()}</aside><section><div class="results-head"><h3>${query?'搜索结果':'为你发现'} <small class="muted">${a.length} 个岗位</small></h3><select aria-label="排序" data-sort><option value="recent" ${sort==='recent'?'selected':''}>最近核验</option><option value="salary" ${sort==='salary'?'selected':''}>月薪从高到低</option></select></div>${a.length?a.slice((pageNo-1)*count,pageNo*count).map(jobCard).join(''):empty('暂时没有匹配的职位','试着减少筛选条件，机会可能就在下一页。',btn('清空筛选','clearfilters','','soft'))}<div class="row between space"><span class="tiny muted">筛选和翻页免费 · 查看新详情才扣次</span><div class="row">${btn('‹','pagination',Math.max(1,pageNo-1),'small')}<span class="tiny">${pageNo} / ${total}</span>${btn('›','pagination',Math.min(total,pageNo+1),'small')}</div></div>${sort==='salary'?'<p class="tiny muted">日薪与未披露薪资排在月薪岗位之后，不作直接换算。</p>':''}</section><aside class="stack aside">${quota()}<div class="card"><h3>每一次选择，都有依据</h3><p class="muted">展示来源与核验时间。详情保留原始申请渠道，最终以招聘方信息为准。</p>${link('了解数据如何整理 →','about','','text')}</div><div class="note demo">演示数据<br><span class="tiny">此处职位和公司均为虚构。</span></div></aside></div>`}
function detailPage(){const j=job(id)||s.jobs[0],seen=s.logged&&s.unlocks[j.id],b=M.balance(s),available=j.published&&j.status==='在招';return `${link('‹ 返回职位列表','jobs','','text')}<div class="detail-grid"><article class="card detail-main"><div class="detail-top"><div class="row between"><div><h1>${esc(j.title)}</h1><div class="meta">${esc(j.city)} · ${esc(j.exp)} · ${esc(j.education)} · ${esc(j.type)}</div></div><strong class="salary">${esc(j.salary)}</strong></div><div class="tags">${j.tags.map(t=>`<span>${esc(t)}</span>`).join('')}${pill(j.status,available?'green':'orange')}${seen?pill('已解锁','blue'):''}</div><div class="row between"><span class="tiny muted">${esc(j.source)} · 核验于 ${esc(j.verified)}</span>${btn(s.favorites.includes(j.id)?'♥ 已收藏':'♡ 收藏','favorite',j.id,'small')}</div></div><div class="section"><h3>岗位摘要</h3><p class="prose">${esc(j.summary)}</p></div>${seen?`${!available?'<div class="note warning">该岗位已停止招聘，仅保留历史详情供回看。申请入口已关闭。</div>':''}<div class="section"><h3>工作职责</h3><p class="prose">${esc(j.description)}</p></div><div class="section"><h3>任职要求</h3><p class="prose">${esc(j.requirements)}</p></div><div class="section"><h3>来源与申请</h3><div class="note">官方来源 · ${esc(j.source)}<p class="tiny">示例域名：careers.example.com。真实产品将跳转到原始招聘页面。</p>${available?btn('查看原始申请渠道 ↗','source-demo',j.id,'soft'):pill('申请已关闭','orange')}</div></div><div class="note demo">本岗位已解锁，重复查看不扣次数，跨天或会员到期后仍可回看。</div>`:!available?empty('岗位暂不可解锁','已结束或下架的岗位不会扣除额度。'): `<div class="lockbox"><div class="lock-icon">▣</div><h2>这个机会，值得进一步了解</h2><p>解锁后可查看完整职责、要求和原始申请渠道。</p><p class="tiny">${s.logged?`剩余 ${b.base} 次今日额度${b.credit?` + ${b.credit} 次补偿额度`:''}`:'登录即可获得每天 1 次免费解锁额度'} · 同一岗位重复查看免费</p>${btn(s.logged?(b.base+b.credit?'消耗 1 次，解锁详情':'今日额度已用完 · 查看会员'):'登录后解锁详情','unlock',j.id,'primary')}<p class="tiny muted">确认解锁并成功获得详情后扣次，失败不扣次。</p></div>`}<div class="detail-actions">${btn('⚑ 信息有误 / 岗位失效','feedback',j.id,'text')}<span class="tiny muted">请勿向招聘方支付任何求职费用</span></div></article><aside class="stack aside"><div class="card"><div class="row"><span class="company-logo ${j.tone}">${esc(j.letter)}</span><h3>${esc(j.company)}</h3></div><p class="muted">${esc(j.industry)} · ${esc(j.city)}</p>${link('查看公司在招职位 →','company',j.company,'text')}</div>${quota()}</aside></div>`}
function companyPage(){const name=id||'青禾科技',jobs=s.jobs.filter(j=>j.company===name&&j.published&&j.status==='在招');return `${head(esc(name),'公司信息与岗位均为虚构演示数据',link('返回职位','jobs','','small'))}<div class="card space"><h3>公司简介</h3><p class="prose">一家重视产品体验与团队协作的示例企业。企业介绍在正式产品中仅从可验证来源整理，不由 AI 补写未确认信息。</p><span class="muted">在招 ${jobs.length} 个岗位 · 来源：企业招聘官网</span></div>${jobs.map(jobCard).join('')||empty('暂无在招职位','可返回列表查看其他公司。')}`}
function favoritesPage(){return head('我的收藏','先收藏，再慢慢挑选。收藏不消耗额度。')+(!s.logged?empty('登录后同步收藏','网站与小程序使用同一个账户。',link('去登录','login','','primary')):s.favorites.length?s.favorites.map(job).filter(Boolean).map(jobCard).join(''):empty('把心动的机会留在这里','在职位卡片上点一下爱心，即可收藏。',link('发现职位','jobs','','primary')))}
function loginPage(){return `<div class="login-card card"><div class="login-mark">职</div><h1>欢迎来到职遇</h1><p class="muted">让每一次求职，都多一点确定。</p><div class="note demo">原型使用演示账号“林同学”，不会读取手机号或微信资料。</div><form data-form="login"><label class="checkbox space"><input type="checkbox" name="agreement" required>我已阅读服务说明与隐私规则（演示）</label><button class="btn primary full">${mode==='mini'?'微信一键登录（演示）':'使用演示账号登录'}</button></form>${link('查看服务与数据说明','about','','text full')}<p class="tiny muted">正式版账号合并与微信身份绑定将在开发时实现。</p></div>`}
function minePage(){if(!s.logged)return head('我的')+empty('登录后管理你的机会','查看会员权益、收藏与历史记录。',link('登录 / 注册','login','','primary'));const b=M.balance(s);return `<div class="account-head"><span class="avatar">林</span><div><h1>你好，林同学</h1><p class="muted">今天也离心仪的工作更近一步。</p></div>${pill(b.tier==='普通'?'普通用户':b.tier+' 会员')}</div><div class="stat-grid space">${[['今日剩余',b.base],['补偿额度',b.credit],['已看岗位',Object.keys(s.unlocks).length],['我的收藏',s.favorites.length]].map(([t,v])=>`<div class="stat card"><span>${t}</span><strong>${v}</strong></div>`).join('')}</div><div class="split"><div class="stack">${quota()}<div class="card"><h3>我的服务</h3><button class="btn soft full" data-act="binding">账号关联状态（演示）</button>${[['history','已看岗位与额度记录'],['orders','订单与售后'],['about','服务与数据说明']].map(([p,t])=>`<div class="row between section"><span>${t}</span>${link('查看 →',p,'','text')}</div>`).join('')}</div></div><div class="card"><h3>我的反馈</h3>${s.feedback.length?s.feedback.map(f=>`<div class="section"><div class="row between"><strong>${esc(job(f.job)?.title)}</strong>${pill(f.status,f.status==='待处理'?'orange':'green')}</div><p class="tiny muted">${esc(f.reason)} · ${date(f.time)}</p>${f.compensated?'<p class="tiny">补偿 1 次，有效期 7 天，优先使用。</p>':''}</div>`).join(''):empty('暂无反馈','遇到过期或错误的信息，可以在岗位详情提交反馈。')}</div></div>${btn('退出演示账号','logout','','text')}`}
function aboutPage(){return head('数据透明，选择才更安心','信息整理服务说明 · 原型草案')+`<div class="card prose"><h2>我们如何整理岗位</h2><p>从允许访问、可追溯的数据源定期采集，经 AI 提取、规则校验、去重与人工审核后展示。缺失的薪资、地点或经验字段标记为“未披露”，不由模型猜测。</p><h2>怎样使用额度</h2><p>搜索、筛选、翻页和收藏免费。首次成功解锁一个岗位消耗 1 次，重复查看该岗位不再扣次。普通用户每天 1 次，V1 20 次，V2 100 次，V3 200 次，每日北京时间 00:00 重置，不累计。</p><h2>会员与支付</h2><p>购买入口在微信小程序，网站可查看权益和订单。演示按 30 天服务期设计，价格待定；有效期内只开放同级续费。真实微信支付能力、经营资质和不同设备的可购范围需在上线前确认。</p><h2>反馈与补偿</h2><p>已解锁岗位确实无效，经核实可补偿 1 次独立额度，有效期 7 天。同一岗位不重复补偿。补偿优先使用，不影响原来的回看权限。</p><h2>售后与边界</h2><p>尚未开始的服务段可进入退款流程；已开始服务的订单由客服核算，具体金额规则待定。平台提供招聘信息整理，不承诺招聘结果。岗位真实性与申请条件以招聘方原始信息为准。</p><div class="note demo">当前为交互原型。没有真实岗位、真实招聘申请、真实支付、真实 AI 采集，也不会上传你在本原型填写的内容。</div></div>`}
function memberPage(){const b=M.balance(s);return head('把握更多值得的机会','按需查看，每一次解锁都有明确记录。')+`<div class="notice-strip row between"><div>当前：<b>${b.tier==='普通'?'普通用户':b.tier+' 会员'}</b> · 今日剩余 ${b.base} 次${b.tier!=='普通'?` · 有效期至 ${date(s.until)}`:''}</div>${link('额度记录 →','history','','text')}</div><div class="plans">${['V1','V2','V3'].map((level,i)=>`<div class="plan ${i===0?'featured':''}">${i===0?pill('轻量求职推荐'):pill(i===1?'积极求职':'高频探索','blue')}<h2>${level} 会员</h2><div class="big">${M.plans[level]} <small>次 / 天</small></div><p class="muted">每日可解锁 ${M.plans[level]} 个新岗位</p><div class="price">价格待定 <small>/ 30 天（建议方案）</small></div><div class="prose tiny"><p>✓ 无限次搜索与筛选<br>✓ 已解锁岗位免费回看<br>✓ 网站与小程序共享权益<br>✓ 透明的额度使用记录</p></div>${btn(!s.planEnabled[level]?'暂未上架':b.tier===level?'同级续费':b.tier!=='普通'?'有效期内不支持跨级':mode==='web'?'前往小程序体验购买':'选择 '+level,'choose-plan',level,i===0?'primary full':'full')}</div>`).join('')}</div><div class="note space">免费用户每天 1 次。未使用的每日额度不累计；购买当天按新上限减去当天已用次数。演示服务期 30 天，最终价格及服务期需确认。</div><div class="note demo">所有支付均为模拟。正式购买入口将依据小程序审核结果及设备可用性展示。${!s.paymentAvailable?'<p><b>当前演示环境：暂不支持购买。</b></p>':''}</div>`}
function checkoutPage(){const level=['V1','V2','V3'].includes(id)?id:'V1';if(mode==='web')return head('在微信小程序完成购买','网站与小程序共享同一账户的会员权益。')+empty('切换到小程序购买流程','原型将直接切换到小程序界面，不会发起真实微信支付。',btn('打开小程序原型','mini-checkout',level,'primary'));return `<div class="checkout">${head('确认会员订单','请确认权益内容及服务规则。')}<div class="card"><div class="row between"><h2>${level} 会员</h2>${pill(M.plans[level]+' 次 / 天')}</div><div class="summary-pair"><span>服务周期</span><strong>30 天（建议方案）</strong></div><div class="summary-pair"><span>开始时间</span><span>${M.tier(s)===level?'当前有效期结束后':'权益确认后立即开始'}</span></div><div class="summary-pair"><span>套餐价格</span><strong>待定 · 不收取费用</strong></div><div class="summary-pair"><span>支付方式</span><span>微信支付（模拟）</span></div><form data-form="checkout" data-level="${level}"><label class="checkbox space"><input type="checkbox" name="agreement" required>同意会员服务及售后规则</label><button class="btn primary full">创建演示订单</button></form>${link('阅读服务规则','about','','text full')}</div><div class="note demo space">支付由服务器确认后发放权益。客户端成功提示不会直接决定到账。</div></div>`}
function findOrder(){return s.orders.find(o=>o.id===id)||s.orders[0]}
function paymentPage(){const o=findOrder();if(!o)return head('支付结果')+empty('还没有订单','选择会员方案后创建一笔演示订单。',link('查看会员','member','','primary'));const ok=o.grant&&o.refund!=='退款成功',text=ok?'会员权益已到账':o.status==='已支付'?'支付成功，权益发放中':o.status==='确认中'?'正在确认支付结果':o.last==='cancel'?'你已取消本次支付':o.last==='fail'?'支付未完成':o.status==='已关闭'?'订单已关闭':'等待支付';return `<div class="checkout"><div class="card status-hero"><div class="status-circle">${ok?'✓':'◷'}</div><h1>${text}</h1><p class="muted">${o.id} · ${o.level} 会员</p><div class="note demo">这是一笔演示订单，没有实际扣款。</div>${ok?`<p>每日 ${M.plans[o.level]} 次 · 本次服务段至 ${date(o.end)}</p>${link('继续发现职位','jobs','','primary')}`:o.status==='已关闭'?link('重新选择会员','member','','primary'):o.status==='已支付'||o.status==='确认中'?btn('模拟服务端确认 / 重试发放','confirm-pay',o.id,'primary'):btn('模拟微信支付','pay-modal',o.id,'primary')}<div>${link('订单详情与售后','order',o.id,'text')}</div></div></div>`}
function ordersPage(){return head('我的订单','支付进度、会员服务段与售后记录。')+(!s.logged?empty('登录后查看订单','使用同一账号同步订单信息。',link('去登录','login','','primary')):s.orders.length?s.orders.map(o=>`<div class="card order-card"><div class="row between"><span class="muted tiny">${o.id} · ${date(o.created)}</span>${pill(o.refund||o.status,o.grant?'green':'orange')}</div><div class="row between section"><div><h2>${o.level} 会员</h2><p class="muted">30 天 · 每日 ${M.plans[o.level]} 次</p></div><strong>演示订单 · 价格待定</strong></div><div class="row between"><span class="tiny muted">${o.grant?'权益已发放':'权益尚未发放'}</span>${link('查看详情','order',o.id,'small')}</div></div>`).join(''):empty('还没有订单','你可以先使用每天 1 次的免费额度。',link('了解会员','member','','primary')))}
function orderPage(){if(!s.logged)return loginPage();const o=findOrder();if(!o)return ordersPage();return `<div class="checkout">${head('订单详情',o.id,link('全部订单','orders','','small'))}<div class="card"><div class="row between"><h2>${o.level} 会员</h2>${pill(o.refund||o.status)}</div>${[['订单金额','价格待定（模拟，无扣款）'],['创建时间',date(o.created)],['权益状态',o.grant?'已到账':'未到账'],['服务开始',o.start?date(o.start):'待确认'],['服务结束',o.end?date(o.end):'待确认'],['售后状态',o.refund||'未申请']].map(([k,v])=>`<div class="summary-pair"><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="row wrap space">${o.status==='待支付'?btn('继续支付','pay-modal',o.id,'primary')+btn('关闭订单','close-order',o.id):o.status==='确认中'?link('查看确认进度','payment',o.id,'primary'):''}${o.status==='已支付'&&!o.grant&&o.refund!=='退款成功'?btn('检查权益到账','confirm-pay',o.id,'primary'):''}${o.status==='已支付'&&!o.refund?btn('申请售后','refund-request',o.id):''}</div></div><div class="note space">未开始服务段进入退款审核；当前已开始服务需人工核算。额度和已看岗位不会因退款重复补发。</div></div>`}
function historyPage(){if(!s.logged)return head('已看与额度')+empty('登录后查看记录','已解锁岗位随时免费回看。',link('去登录','login','','primary'));const b=M.balance(s);return head('已看与额度','同一岗位只解锁一次，跨天与会员到期后仍可回看。')+`<div class="stat-grid space">${[['今日上限',b.limit],['今日已用',b.used],['基础剩余',b.base],['补偿剩余',b.credit]].map(([k,v])=>`<div class="stat card"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><h2>已看岗位</h2>${Object.keys(s.unlocks).length?Object.keys(s.unlocks).map(job).filter(Boolean).map(jobCard).join(''):empty('还没解锁过岗位','先筛选，再决定是否查看详情。',link('发现职位','jobs','','primary'))}<h2>额度流水</h2><div class="card table-card">${table(['时间','岗位','类型','变化'],s.ledger.map(l=>[date(l.time),esc(job(l.job)?.title),l.kind,(l.amount>0?'+':'')+l.amount]))}</div><p class="tiny muted">补偿额度有效期 7 天，优先消耗最早到期的一次。</p>`}
function adminShell(){if(!s.adminLogged&&page!=='login')return adminLogin();if(page==='login')return adminLogin();const groups=[['概览',['dashboard']],['内容与采集',['jobs','review','sources','runs','ai','dictionary']],['用户与交易',['feedback','users','plans','orders','refunds','ledger']]];return `<div class="admin-layout"><aside class="sidebar"><div class="brand"><span class="logo">职</span><div><strong>职遇</strong><small>运营管理后台</small></div></div>${groups.map(([t,p])=>`<div class="nav-group"><label>${t}</label>${p.map(p=>`<button class="side-link ${page===p?'active':''}" data-act="go" data-id="${p}"><span>${icons[p]}</span>${A[p][1]}${p==='review'&&s.jobs.some(j=>!j.published)?'<b class="pill orange">'+s.jobs.filter(j=>!j.published).length+'</b>':''}</button>`).join('')}</div>`).join('')}<div class="note demo tiny">原型环境<br>数据仅保存在本浏览器</div></aside><section class="admin-main"><header class="admin-top"><div class="muted">工作空间 <span> / </span><strong>${title()[1]}</strong></div><div class="row">${pill('演示环境','orange')}<span class="avatar">管</span>${btn('退出','admin-logout','','text')}</div></header><main class="admin-content">${adminPage()}</main></section></div>`}
function adminLogin(){return `<div class="page-wrap"><div class="login-card card"><div class="login-mark">职</div><h1>运营管理后台</h1><p class="muted">招聘数据、用户权益与服务质量。</p><form data-form="admin-login"><div class="field"><label>演示账号</label><input value="operator@zhiyu.demo" readonly></div><div class="note demo space">原型不验证密码，不代表正式后台权限。正式产品需管理员认证和权限控制。</div><button class="btn primary full">进入演示后台</button></form></div></div>`}
function adminPage(){switch(page){case'dashboard':return dashboard();case'jobs':return adminJobs();case'edit':return editJob();case'review':return reviewPage();case'sources':return sourcesPage();case'runs':return runsPage();case'ai':return aiPage();case'dictionary':return dictionaryPage();case'feedback':return feedbackPage();case'users':return usersPage();case'plans':return plansPage();case'orders':return adminOrders();case'refunds':return refundsPage();case'ledger':return ledgerPage();default:return dashboard()}}
function dashboard(){const stats=[['在招岗位',s.jobs.filter(j=>j.published&&j.status==='在招').length,'可在用户端查看'],['待审核',s.jobs.filter(j=>!j.published).length,'审核通过后发布'],['待处理反馈',s.feedback.filter(f=>f.status==='待处理').length,'关注失效与错误信息'],['权益待发放',s.orders.filter(o=>o.status==='已支付'&&!o.grant&&o.refund!=='退款成功').length,'支付确认后补发']];return head('工作台','把可靠的信息，交到需要的人手里。',pill(M.day(s)+' · 北京时间','blue'))+`<div class="stat-grid space">${stats.map(([t,v,d])=>`<div class="stat card"><span>${t}</span><strong>${v}</strong><small>${d}</small></div>`).join('')}</div><div class="dashboard-grid"><div class="card"><div class="row between"><h3>今日采集概况</h3>${link('全部任务 →','runs','','text')}</div>${table(['数据源','状态','发现 / 新增'],s.runs.slice(0,4).map(r=>[esc(r.source),pill(r.status,r.status==='失败'?'red':'green'),r.found+' / '+r.added]))}<div class="note tiny">演示任务记录；执行采集仅创建本地审核样例，不访问外部网站。</div></div><div class="card"><h3>待办事项</h3>${[['review','审核待发布岗位'],['feedback','处理用户反馈'],['orders','检查支付与权益'],['refunds','处理退款申请']].map(([p,t])=>`<div class="section row between"><span>${t}</span>${link('处理 →',p,'','text')}</div>`).join('')}</div></div><div class="card space"><h3>内容进入用户端的路径</h3><div class="row wrap">${['允许访问的数据源','AI 提取','规则校验 / 去重','人工审核','发布展示','反馈纠错'].map((t,i)=>`${i?'<span class="muted">→</span>':''}${pill(t,i===3?'orange':'green')}`).join('')}</div></div>`}
function adminJobs(){return head('岗位管理','管理招聘状态与可见范围。',btn('新增岗位','new-job','','primary'))+`<div class="card table-card"><div class="table-tools"><span>全部 ${s.jobs.length} 条</span><span class="tiny muted">未发布岗位在用户端不可见</span></div>${table(['岗位 / 公司','城市 / 经验','状态','来源 / 核验','操作'],s.jobs.map(j=>[`<strong>${esc(j.title)}</strong><small>${esc(j.company)}</small>`,esc(j.city)+'<small>'+esc(j.exp)+'</small>',pill(!j.published?'待审核':j.status,!j.published?'orange':j.status==='在招'?'green':'red'),esc(j.source)+'<small>'+esc(j.verified)+'</small>',`<div class="table-actions">${link('编辑','edit',j.id,'text')}${btn(j.status==='在招'?'结束招聘':'恢复招聘','job-status',j.id,'text')}${j.published?btn('下架','unpublish',j.id,'text'):link('审核','review','','text')}</div>`]))}</div>`}
function editJob(){const j=job(id)||s.jobs[0];return head('编辑岗位','修改后保存为待审核，审核通过才会再次展示。',link('返回岗位','jobs','','small'))+`<div class="card"><form data-form="job-edit" data-id="${j.id}" class="form-grid">${[['title','岗位名称'],['company','公司'],['city','城市'],['industry','行业'],['exp','工作经验'],['education','学历'],['salary','薪资'],['category','职能'],['source','来源名称'],['type','招聘类型']].map(([k,t])=>`<div class="field"><label>${t}</label><input name="${k}" value="${esc(j[k])}" required></div>`).join('')}${[['summary','公开摘要'],['description','岗位职责'],['requirements','任职要求']].map(([k,t])=>`<div class="field wide"><label>${t}</label><textarea name="${k}" rows="3" required>${esc(j[k])}</textarea></div>`).join('')}<div class="wide row"><button class="btn primary">保存并提交审核</button><span class="tiny muted">缺失字段填写“未披露”，不得补写事实。</span></div></form></div>`}
function reviewPage(){const a=s.jobs.filter(j=>!j.published);return head('内容审核','核对原文、提取字段与重复关系后再发布。')+a.map(j=>`<div class="card space"><div class="row between"><div><h2>${esc(j.title)}</h2><p class="muted">${esc(j.company)} · ${esc(j.source)}</p></div>${pill('待人工审核','orange')}</div><div class="split"><div class="review-evidence"><h3>采集原文（演示）</h3><p>${esc(j.title)}，${esc(j.city)}，${esc(j.salary)}。${esc(j.description)}</p><p class="tiny muted">来源内容快照用于追溯，本原型为示例文本。</p></div><div><h3>结构化字段</h3><p>经验：${esc(j.exp)}　学历：${esc(j.education)}</p><p>行业：${esc(j.industry)}　职能：${esc(j.category)}</p><div class="note warning">${esc(j.reason||'等待人工核验字段与招聘状态')}</div></div></div><div class="row wrap space">${btn('审核通过并发布','publish',j.id,'primary')}${link('修改字段','edit',j.id)}${btn('标记重复 / 不发布','reject-job',j.id,'text')}</div></div>`).join('')+(a.length?'':empty('待审核队列已清空','新采集或修改的岗位会进入这里。',link('查看采集任务','runs','','primary')))}
function sourcesPage(){return head('数据源管理','只接入有权访问的渠道，保留来源和采集记录。',btn('＋ 添加数据源','source-edit','','primary'))+`<div class="card table-card">${table(['数据源 / 地址','采集时间','状态','最近运行','操作'],s.sources.map(x=>[`<strong>${esc(x.name)}</strong><small>${esc(x.url)}</small>`,esc(x.schedule),pill(x.enabled?'已启用':'已暂停',x.enabled?'green':'orange'),esc(x.last),`<div class="table-actions">${btn('编辑','source-edit',x.id,'text')}${btn(x.enabled?'暂停':'启用','source-toggle',x.id,'text')}${btn('模拟采集','run-source',x.id,'text')}</div>`]))}</div><div class="note demo space">此处的采集不会请求网络。定时任务、授权检查与抓取频率控制将在实际服务中实现。</div>`}
function runsPage(){return head('采集任务','查看运行结果、失败原因与入库去向。')+`<div class="card table-card">${table(['任务编号','数据源','状态','发现 / 新增 / 更新','时间','操作'],s.runs.map(r=>[r.id,esc(r.source),pill(r.status,r.status==='失败'?'red':'green'),`${r.found} / ${r.added} / ${r.updated}`,esc(r.time),btn('详情','run-detail',r.id,'text')+(r.status==='失败'?btn('重试','retry-run',r.id,'text'):'')]))}</div>`}
function aiPage(){return head('AI 提取配置','演示字段映射与审核规则，不连接真实模型。')+`<div class="split"><div class="card"><form data-form="ai-config"><h3>提取配置</h3><div class="field space"><label>模型标识（占位）</label><input name="model" value="${esc(s.ai.model)}" required></div><label class="checkbox"><input type="checkbox" checked disabled>提取结果必须经过审核</label><p class="tiny muted">核心字段缺失、低可信或重复候选进入人工审核。</p><button class="btn primary">保存配置</button></form></div><div class="card"><form data-form="ai-sample"><h3>示例提取测试</h3><p class="tiny muted">填写“岗位 / 公司 / 城市 / 薪资”，使用固定分隔规则演示结构化结果。</p><textarea name="sample" rows="4" required>Java 开发 / 青禾科技 / 成都 / 18–28K</textarea><button class="btn soft space">运行演示提取</button></form><div id="sample-result"></div></div></div>`}
function dictionaryPage(){return head('公司与字典','统一行业、职能与公司名称，减少筛选歧义。')+`<div class="card space"><h3>公司列表</h3>${table(['公司','行业','岗位数'],[...new Set(s.jobs.map(j=>j.company))].map(n=>[esc(n),esc(s.jobs.find(j=>j.company===n).industry),s.jobs.filter(j=>j.company===n).length]))}</div><div class="split">${['industry','category'].map(k=>`<div class="card"><h3>${k==='industry'?'行业':'职能'}字典</h3><div class="tags space">${s.dictionary[k].map(t=>`<span>${esc(t)}</span>`).join('')}</div><form data-form="dictionary" data-key="${k}" class="row"><input name="value" placeholder="新增字典项" required maxlength="20"><button class="btn soft">添加</button></form></div>`).join('')}</div>`}
function feedbackPage(){return head('用户反馈','核实错误后修正内容，为受影响的解锁提供补偿。')+`<div class="card table-card">${table(['反馈 / 用户','岗位','原因 / 说明','状态','操作'],s.feedback.map(f=>[f.id+'<small>林同学</small>',esc(job(f.job)?.title),esc(f.reason)+'<small>'+esc(f.note||'未补充说明')+'</small>',pill(f.status,f.status==='待处理'?'orange':'green'),`<div class="table-actions">${s.unlocks[f.job]&&!f.compensated?btn('核实并补偿 1 次','compensate',f.id,'text'):''}${f.status==='待处理'?btn('不符合补偿','reject-feedback',f.id,'text'):''}${link('修正岗位','edit',f.job,'text')}</div>`]))}</div><p class="tiny muted">补偿需原岗位已经解锁；同一岗位只补偿一次，有效期 7 天。</p>`}
function usersPage(){const b=M.balance(s);return head('用户与会员','统一账户下的网站与小程序权益。')+`<div class="card table-card">${table(['用户','会员等级','有效期','今日额度','补偿','操作'],[['林同学<small>DEMO-USER-001</small>',pill(b.tier),s.until?date(s.until):'—',`${b.base} / ${b.limit}`,b.credit,btn('查看用户详情','user-detail','','text')]])}</div><div class="note demo space">原型只有一个共享演示用户。真实手机号 / 微信身份合并不在原型中执行。</div>`}
function plansPage(){return head('套餐配置','额度分层已确定，价格与服务周期仍待确认。')+`<div class="card table-card">${table(['等级','每日额度','周期','价格','状态','操作'],['V1','V2','V3'].map(l=>[l,M.plans[l]+' 次','30 天（建议）','待定',pill(s.planEnabled[l]?'演示上架':'已下架',s.planEnabled[l]?'green':'orange'),btn(s.planEnabled[l]?'下架':'上架','toggle-plan',l,'text')]))}</div><div class="note warning space">原型不填入虚构售价。正式开放付款前需确定定价、退款金额规则及微信支付适用范围。</div>`}
function adminOrders(){return head('支付订单','以服务端支付确认结果发放权益，重复通知不重复发放。')+`<div class="card table-card">${table(['订单 / 用户','套餐','支付状态','权益状态','服务段','操作'],s.orders.map(o=>[o.id+'<small>林同学</small>',o.level+'<small>价格待定</small>',pill(o.status,o.status==='已支付'?'green':'orange'),o.refund==='退款成功'?'已退款':o.grant?'已发放':esc(o.problem||'未发放'),o.start?date(o.start)+'<small>至 '+date(o.end)+'</small>':'—',btn('核对订单','admin-order-detail',o.id,'text')+(o.status==='已支付'&&!o.grant&&o.refund!=='退款成功'?btn('补发权益','grant',o.id,'text'):'')]))}</div>`}
function refundsPage(){const a=s.orders.filter(o=>o.refund);return head('退款与售后','检查服务段是否开始，再进入渠道退款流程。')+`<div class="card table-card">${table(['订单','服务开始','售后状态','处理'],a.map(o=>[o.id+'<small>'+o.level+'</small>',o.start?date(o.start):'未发放',pill(o.refund,o.refund==='退款成功'?'green':'orange'),o.refund==='退款成功'?'已完成':`<div class="table-actions">${btn('同意并模拟退款','refund-process',o.id,'text')}${btn('模拟渠道成功','refund-success',o.id,'text')}${btn('模拟退款失败','refund-fail',o.id,'text')}${btn('驳回','refund-reject',o.id,'text')}</div>`]))}</div><div class="note space">已开始服务的订单转人工核算；未开始服务段退款成功后，后续同级服务段顺延衔接，已解锁记录保留。</div>`}
function ledgerPage(){return head('额度流水','追踪每次成功解锁和补偿发放。')+`<div class="card table-card">${table(['时间','用户','岗位','类型','变动'],s.ledger.map(l=>[date(l.time),'林同学',esc(job(l.job)?.title),l.kind,pill((l.amount>0?'+':'')+l.amount,l.amount>0?'green':'blue')]))}</div>`}
function scenarios(){modal('演示工具',`<div class="note demo">仅改变本浏览器的演示状态，不产生真实交易。当前 ${M.day(s)}，${M.tier(s)}，剩余 ${M.balance(s).base} 次。</div><h3>账户与额度</h3><div class="scenario-grid">${[['guest','游客'],['basic','普通用户'],['V1','V1 会员'],['V2','V2 会员'],['V3','V3 会员'],['exhaust','今日额度耗尽'],['nextday','推进到下一天'],['expire','模拟会员到期'],['fail','下次解锁失败'],['unsupported','切换支付可用性']].map(([v,t])=>btn(t,'scenario',v)).join('')}</div><p class="tiny muted">等级切换会重置会员期限用于观察界面，正式交易流请通过会员中心体验。已看和收藏保留。</p>`)}
function catalog(){modal('原型页面目录',`<p class="muted">选择页面直接预览；详情页默认展示样例，订单页需先创建订单。</p><div class="catalog">${Object.entries(mode==='admin'?A:C).map(([p,[code,t]])=>link(`<span class="page-id">${code}</span> ${t}`,p,p==='detail'?'j1':p==='company'?'青禾科技':p==='edit'?'j1':'','full')).join('')}</div><div class="note tiny space">C02 搜索结果复用职位列表；C08 为反馈弹窗。订阅、消息、关注及高级报表列为后续版本，本次不开放。</div>`)}
function paymentModal(oid){if(!s.paymentAvailable){toast('当前环境暂不支持购买，可在演示工具中切换');return}modal('微信支付 · 模拟面板',`<div class="payment-demo"><h2>演示订单 ${esc(oid)}</h2><p>没有真实金额，不会调用微信或发生扣款。</p><div class="payment-options">${[['success','模拟支付成功并到账'],['delayed','支付成功，权益延迟'],['pending','支付结果确认中'],['cancel','取消支付'],['fail','支付失败']].map(([r,t])=>btn(t,'pay-result',oid+'|'+r,r==='success'?'primary':'')).join('')}</div></div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;const act=el.dataset.act,x=el.dataset.id||'';
switch(act){
case'go':{const [p,...parts]=x.split('/');go(p,parts.join('/'));break}
case'mode':go(x==='admin'?'dashboard':'jobs','',x);break;
case'close':close();break;case'catalog':catalog();break;case'scenarios':scenarios();break;
case'binding':bindingDialog();break;case'binding-state':bindingDialog(x);break;
case'reset':modal('重置演示数据','<p>会清除本原型中的收藏、解锁、订单与后台修改，恢复初始样例。</p>',btn('取消','close')+btn('确认重置','reset-confirm','','danger'));break;
case'reset-confirm':s=M.seed();filters={};query='';pageNo=1;save();go('jobs','','web');toast('已恢复初始演示数据');break;
case'scenario':if(x==='guest')s.logged=false;else if(x==='basic'){s.logged=true;s.member='普通';s.until=0}else if(['V1','V2','V3'].includes(x)){s.logged=true;s.member=x;s.until=s.now+30*M.DAY}else if(x==='exhaust'){s.logged=true;s.used[M.day(s)]=M.plans[M.tier(s)];s.credits.forEach(c=>c.used=true)}else if(x==='nextday')s.now+=M.DAY;else if(x==='expire'){s.now=Math.max(s.now,s.until)+1;s.member='普通'}else if(x==='fail')s.failNext=true;else if(x==='unsupported')s.paymentAvailable=!s.paymentAvailable;close();render();toast('演示场景已更新');break;
case'hot':query=x;pageNo=1;render();break;case'clearfilters':filters={};query='';pageNo=1;close();render();break;case'pagination':pageNo=+x;render();break;
case'filters':modal('筛选职位',filterFields(),btn('清空','clearfilters')+btn('查看结果','applyfilters','','primary'));break;case'applyfilters':close();render();break;
case'favorite':if(!needLogin('detail/'+x))break;s.favorites=s.favorites.includes(x)?s.favorites.filter(i=>i!==x):[...s.favorites,x];render();toast(s.favorites.includes(x)?'已收藏，不消耗额度':'已取消收藏');break;
case'unlock':{if(!needLogin('detail/'+x))break;const b=M.balance(s);if(!b.base&&!b.credit&&!s.unlocks[x]){pending='detail/'+x;go('member');toast('今日额度已用完，已解锁岗位仍可免费回看');break}const r=M.unlock(s,x);render();toast({ok:'解锁成功，消耗 1 次额度',repeat:'已解锁，免费回看',failed:'本次请求失败，没有扣除额度，请重试',unavailable:'岗位已失效，不扣次',quota:'额度不足',login:'请先登录'}[r]);break}
case'logout':s.logged=false;go('jobs');break;
case'source-demo':modal('原始申请渠道',`<div class="note demo">这是虚构岗位，没有真实投递链接。</div><p>正式版会展示原始来源链接、核验时间和跳转提示，由用户在招聘方渠道完成申请。</p><p class="tiny muted">模拟来源：careers.example.com</p>`,btn('知道了','close','','primary'));break;
case'feedback':if(!needLogin('detail/'+x))break;modal('反馈岗位信息',`<form data-form="feedback" data-id="${esc(x)}"><div class="field"><label>问题类型</label><select name="reason"><option>岗位已结束 / 链接失效</option><option>信息与原文不符</option><option>疑似重复岗位</option><option>其他问题</option></select></div><div class="field space"><label>补充说明（可选）</label><textarea name="note" maxlength="500" rows="4" placeholder="描述你发现的问题，帮助我们核实"></textarea></div><p class="tiny muted">已解锁岗位经核实后可获一次补偿，同岗位不重复补偿。</p><button class="btn primary full">提交反馈</button></form>`);break;
case'choose-plan':if(!needLogin('member'))break;if(!s.paymentAvailable){toast('当前环境暂不支持购买');break}if(!s.planEnabled[x]){toast('该套餐暂未上架');break}if(M.tier(s)!=='普通'&&M.tier(s)!==x){toast('有效期内仅开放同级续费');break}go('checkout',x);break;
case'mini-checkout':go('checkout',x,'mini');break;case'pay-modal':paymentModal(x);break;
case'pay-result':{const[oid,r]=x.split('|');M.pay(s,oid,r);close();go('payment',oid);render();break}
case'confirm-pay':{const o=s.orders.find(o=>o.id===x);if(o?.refund==='退款成功'){toast('该订单已退款');break}M.pay(s,x,'success');render();toast('已模拟服务端核对，重复确认不重复发放');break}
case'close-order':{const o=s.orders.find(o=>o.id===x);if(o?.status==='待支付')o.status='已关闭';render();break}
case'refund-request':modal('申请订单售后',`<p>未开始的服务段可申请退款；已开始的服务需人工核算，具体金额规则待定。</p><div class="note demo">演示不会产生真实退款。</div>`,btn('暂不申请','close')+btn('提交申请','refund-submit',x,'primary'));break;
case'refund-submit':M.refund(s,x,'request');close();render();toast('售后申请已提交，可切换后台处理');break;
case'admin-logout':s.adminLogged=false;go('login');break;
case'new-job':{const j={...s.jobs[0],id:'j'+(s.jobs.length+1),title:'待编辑的新岗位',published:false,reason:'新建岗位待审核',tags:['待核验']};s.jobs.push(j);go('edit',j.id);break}
case'job-status':{const j=job(x);j.status=j.status==='在招'?'已结束':'在招';render();toast('招聘状态已更新');break}
case'unpublish':job(x).published=false;job(x).reason='人工下架，等待复核';render();toast('已从用户端下架');break;
case'publish':job(x).published=true;job(x).reason='';render();toast('审核通过，用户端已可见');break;
case'reject-job':job(x).reason='已标记重复候选，需修改或确认后发布';render();toast('已标记不发布，保留审核记录');break;
case'source-edit':{const source=s.sources.find(v=>v.id===x)||{name:'',url:'',schedule:'每日 09:00'};modal(x?'编辑数据源':'添加数据源',`<form data-form="source" data-id="${esc(x)}">${[['name','来源名称'],['url','允许访问的来源地址'],['schedule','执行时间']].map(([k,t])=>`<div class="field space"><label>${t}</label><input name="${k}" type="${k==='url'?'url':'text'}" value="${esc(source[k])}" required></div>`).join('')}<p class="tiny muted">此表仅保存配置样例，不验证权限或执行抓取。</p><button class="btn primary full">保存数据源</button></form>`);break}
case'source-toggle':{const v=s.sources.find(v=>v.id===x);v.enabled=!v.enabled;render();break}
case'run-source':{const v=s.sources.find(v=>v.id===x);if(!v.enabled){toast('请先启用数据源');break}runSource(v);render();toast('模拟采集完成，新增样例已进入审核队列');break}
case'run-detail':{const r=s.runs.find(v=>v.id===x);modal('采集任务详情',`<div class="kv"><b>${r.id}</b><p>${esc(r.source)} · ${esc(r.status)}</p><p>发现 ${r.found} 条，新增 ${r.added} 条，更新 ${r.updated} 条。</p><div class="note ${r.status==='失败'?'warning':''}">${r.status==='失败'?'模拟错误：来源请求超时。可重试，正式版需退避与频率限制。':'演示处理完成。新增内容等待审核后才会进入用户端。'}</div></div>`,btn('关闭','close'));break}
case'retry-run':{const r=s.runs.find(v=>v.id===x),v=s.sources.find(v=>v.name===r.source);if(v&&!v.enabled){toast('数据源已暂停');break}r.status='成功';r.found=1;r.added=1;r.updated=0;addCandidate(r.source);render();toast('模拟重试成功，候选进入审核');break}
case'compensate':toast(M.compensate(s,x)?'补偿 1 次已到账，有效期 7 天':'无法重复补偿或该岗位尚未解锁');render();break;
case'reject-feedback':s.feedback.find(f=>f.id===x).status='已核实，无需补偿';render();break;
case'user-detail':modal('用户详情',`<h3>林同学 · DEMO-USER-001</h3><p>等级 ${M.tier(s)}，已看 ${Object.keys(s.unlocks).length} 个岗位，收藏 ${s.favorites.length} 个。</p><p>今日基础额度 ${M.balance(s).base}，独立补偿 ${M.balance(s).credit} 次。</p><div class="note tiny">账号绑定、管理员改权和风险操作审计在正式开发时接入。</div>`);break;
case'toggle-plan':s.planEnabled[x]=!s.planEnabled[x];render();break;
case'grant':toast(M.grant(s,x)?'权益发放完成；重复发放不会延长服务':'当前订单不满足发放条件');render();break;
case'admin-order-detail':{const o=s.orders.find(o=>o.id===x);modal('支付核对',`<h3>${o.id}</h3><p>支付：${o.status} · 权益：${o.grant?'已发放':'未发放'}</p><p>套餐 ${o.level} · 金额待定 · 演示渠道</p><div class="note demo">正式实现需验签、核对商户号 / 订单 / 金额并保存渠道交易号。原型仅演示状态变化。</div>`,o.status==='确认中'?btn('模拟渠道确认已支付','admin-confirm',o.id,'primary'):btn('关闭','close'));break}
case'admin-confirm':M.pay(s,x,'delayed');close();render();toast('已模拟确认支付，可补发权益');break;
case'refund-process':{const o=s.orders.find(o=>o.id===x);if(o.grant&&o.start<=s.now){o.refund='需人工核算';toast('该服务段已开始，需人工核算')}else {M.refund(s,x,'processing');toast('已进入模拟退款渠道')}render();break}
case'refund-success':toast(M.refund(s,x,'success')?'模拟退款成功，服务段已更新':'该服务段已开始，转人工核算');render();break;
case'refund-fail':M.refund(s,x,'fail');render();break;case'refund-reject':M.refund(s,x,'reject');render();break;
}
save();});
function addCandidate(source){const j={...s.jobs[8],id:'j'+(s.jobs.length+1),title:'运营分析专员（采集样例）',source,published:false,status:'在招',reason:'新采集内容需核对原文',category:'运营',tags:['数据分析','运营'],verified:date(s.now)};s.jobs.push(j)}
function runSource(v){addCandidate(v.name);v.last=date(s.now);s.runs.unshift({id:'TASK-DEMO-'+(s.runs.length+1),source:v.name,status:'成功',found:1,added:1,updated:0,time:date(s.now)})}
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;pageNo=1;if(!$('#modal').open)render()}else if(e.target.hasAttribute('data-sort')){sort=e.target.value;render()}});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const d=Object.fromEntries(new FormData(f)),type=f.dataset.form;
switch(type){
case'search':query=d.query.trim();pageNo=1;render();break;
case'login':s.logged=true;{const[p,...a]=(pending||'jobs').split('/');pending='';go(p,a.join('/'))}toast('已登录演示账号');break;
case'feedback':M.report(s,f.dataset.id,d.reason,d.note);close();render();toast('反馈已提交，处理进度可在“我的”查看');break;
case'checkout':{const r=M.order(s,f.dataset.level);if(r.error){if(r.error==='login'){pending='checkout/'+f.dataset.level;go('login')}else toast(r.error)}else go('payment',r.order.id);break}
case'admin-login':s.adminLogged=true;go('dashboard');break;
case'job-edit':{const j=job(f.dataset.id);Object.assign(j,d,{published:false,reason:'人工编辑后待复核'});go('review');toast('已保存，等待审核');break}
case'source':{const v=s.sources.find(v=>v.id===f.dataset.id);if(v)Object.assign(v,d);else s.sources.push({...d,id:'s'+(s.sources.length+1),enabled:true,status:'正常',last:'未运行'});close();render();toast('配置已保存');break}
case'ai-config':s.ai.model=d.model;toast('演示配置已保存');break;
case'ai-sample':{const a=d.sample.split('/').map(x=>x.trim());$('#sample-result').innerHTML=`<div class="note"><b>固定规则演示结果</b>${['岗位','公司','城市','薪资'].map((k,i)=>`<p>${k}：${esc(a[i]||'未披露')}</p>`).join('')}<span class="tiny">需人工审核；这不是实际 AI 输出。</span></div>`;break}
case'dictionary':{const v=d.value.trim(),a=s.dictionary[f.dataset.key];if(v&&!a.includes(v))a.push(v);render();toast('字典已更新');break}
}save();});
window.addEventListener('hashchange',readRoute);readRoute();
})();
